    public const string SchemaText = "FORMATO DE P\u00c1GINA DO URBE (arquivo .page.json)\n{\"version\":1,\"kind\":\"urbe-page\",\"meta\":{...},\"theme\":{...},\"layout\":{...},\"sections\":[{\"type\":\"<bloco>\",\"props\":{...},\"style\":{...}}]}\n\nmeta:\n  - title (text, padr\u00e3o \"P\u00e1gina sem t\u00edtulo\"): T\u00edtulo da p\u00e1gina\n  - description (textarea): Descri\u00e7\u00e3o (buscadores e compartilhamento)\n  - lang (text, padr\u00e3o \"pt-BR\"): Idioma\n  - icon (text, padr\u00e3o \"\u2726\"): \u00cdcone (emoji)\n  - image (URL de imagem): Imagem de compartilhamento\n  - head (code): C\u00f3digo no <head> (estat\u00edsticas, fontes, meta tags)\n\ntheme (tudo opcional; comece pelo preset):\n  - preset (\"aurora\"|\"papel\"|\"grafite\"|\"oceano\"|\"floresta\"|\"entardecer\"|\"neon\"|\"livro\"|\"moderno\"|\"lavanda\", padr\u00e3o \"aurora\"): Tema\n  - mode (\"dark\"|\"light\"|\"auto\"): Modo\n  - headingFont (\"inter\"|\"manrope\"|\"grotesk\"|\"dmsans\"|\"outfit\"|\"playfair\"|\"fraunces\"|\"lora\"|\"merriweather\"|\"garamond\"|\"cormorant\"|\"crimson\"|\"baskerville\"|\"mono\"|\"system\"|\"serif\"): Fonte dos t\u00edtulos\n  - bodyFont (\"inter\"|\"manrope\"|\"grotesk\"|\"dmsans\"|\"outfit\"|\"playfair\"|\"fraunces\"|\"lora\"|\"merriweather\"|\"garamond\"|\"cormorant\"|\"crimson\"|\"baskerville\"|\"mono\"|\"system\"|\"serif\"): Fonte do texto\n  - primary (color): Cor principal\n  - accent (color): Cor de destaque\n  - bg (color): Fundo\n  - surface (color): Superf\u00edcies\n  - text (color): Texto\n  - muted (color): Texto secund\u00e1rio\n  - background (\"plain\"|\"gradient\"|\"mesh\"|\"dots\"|\"grid\"): Fundo da p\u00e1gina\n  - radius (number): Arredondamento\n  - scale (number, padr\u00e3o 1): Tamanho do texto\n  - spacing (\"compact\"|\"comfortable\"|\"airy\", padr\u00e3o \"comfortable\"): Espa\u00e7amento\n  - width (number, padr\u00e3o 1120): Largura m\u00e1xima (px)\n  - shadow (\"none\"|\"soft\"|\"strong\", padr\u00e3o \"soft\"): Sombras\n  - animations (boolean, padr\u00e3o true): Anima\u00e7\u00f5es ao rolar\n  - headingWeight (\"400\"|\"500\"|\"600\"|\"700\"|\"800\"|\"900\"): Peso dos t\u00edtulos\n  - headingCase (\"upper\"|\"small\"): T\u00edtulos em\n  - headingSpacing (number): Espa\u00e7o entre letras dos t\u00edtulos\n  - headingScale (number, padr\u00e3o 1): Tamanho dos t\u00edtulos\n  - lineHeight (number): Altura da linha do texto\n  - buttonStyle (\"solid\"|\"pill\"|\"square\"|\"outline\"|\"soft\", padr\u00e3o \"solid\"): Estilo dos bot\u00f5es\n  - cardStyle (\"elevated\"|\"outlined\"|\"flat\"|\"glass\", padr\u00e3o \"elevated\"): Estilo dos cart\u00f5es\n  - linkStyle (\"underline\"|\"plain\"|\"highlight\", padr\u00e3o \"underline\"): Links no texto\n  - border (color): Cor das bordas\n  - css (code): CSS pr\u00f3prio da p\u00e1gina\n\nlayout:\n  - nav (boolean, padr\u00e3o true): Barra de navega\u00e7\u00e3o\n  - brand (text): Nome na barra\n  - sticky (boolean, padr\u00e3o true): Barra fixa no topo\n  - navCta (text): Bot\u00e3o da barra\n  - navCtaUrl (url): Link do bot\u00e3o da barra\n  - footer (texto Markdown): Rodap\u00e9 (Markdown)\n  - themeToggle (boolean, padr\u00e3o true): Bot\u00e3o claro/escuro\n  - backToTop (boolean, padr\u00e3o true): Bot\u00e3o voltar ao topo\n  - progress (boolean, padr\u00e3o false): Barra de progresso de leitura\n  - format (\"web\"|\"book\", padr\u00e3o \"web\"): Formato\n  - pageSize (\"a5\"|\"6x9\"|\"pocket\"|\"a4\"|\"letter\", padr\u00e3o \"a5\"): Tamanho da p\u00e1gina (livro)\n  - margins (\"narrow\"|\"normal\"|\"wide\", padr\u00e3o \"normal\"): Margens (livro)\n  - pageNumbers (boolean, padr\u00e3o true): N\u00fameros de p\u00e1gina (livro)\n  - runningHead (text): Cabe\u00e7alho das p\u00e1ginas (livro)\n  - chapterStyle (\"word\"|\"words\"|\"number\"|\"roman\"|\"none\", padr\u00e3o \"word\"): N\u00famero dos cap\u00edtulos (livro)\n  - recto (boolean, padr\u00e3o false): Cap\u00edtulos come\u00e7am na p\u00e1gina da direita (livro)\n  - justify (boolean, padr\u00e3o true): Texto justificado com hifeniza\u00e7\u00e3o (livro)\n  - indent (boolean, padr\u00e3o true): Recuo na primeira linha dos par\u00e1grafos (livro)\n\nstyle de cada se\u00e7\u00e3o (opcional):\n  - anchor (text): \u00c2ncora (#link) e item do menu\n  - menu (boolean, padr\u00e3o false): Mostrar no menu\n  - background (\"none\"|\"surface\"|\"primary\"|\"gradient\"|\"image\"|\"inverse\", padr\u00e3o \"none\"): Fundo\n  - image (URL de imagem): Imagem de fundo\n  - padding (\"none\"|\"s\"|\"m\"|\"l\"|\"xl\", padr\u00e3o \"m\"): Espa\u00e7o vertical\n  - width (\"narrow\"|\"normal\"|\"wide\"|\"full\", padr\u00e3o \"normal\"): Largura do conte\u00fado\n  - align (\"left\"|\"center\", padr\u00e3o \"left\"): Alinhamento\n  - bgColor (color): Cor de fundo pr\u00f3pria\n  - textColor (color): Cor do texto pr\u00f3pria\n  - boxed (boolean, padr\u00e3o false): Se\u00e7\u00e3o em caixa (cart\u00e3o)\n  - minHeight (\"none\"|\"half\"|\"screen\", padr\u00e3o \"none\"): Altura m\u00ednima\n  - animation (\"none\"|\"fade\"|\"up\"|\"zoom\"|\"left\"|\"right\"): Anima\u00e7\u00e3o\n  - className (text): Classe CSS\n  - css (code): CSS desta se\u00e7\u00e3o (use & para a se\u00e7\u00e3o)\n  - hidden (boolean, padr\u00e3o false): Ocultar se\u00e7\u00e3o\n\nBLOCOS (type \u2192 props):\n\nhero \u2014 Capa: Abertura com t\u00edtulo grande, texto, bot\u00f5es e imagem opcional.\n  - eyebrow (text): Chamada acima do t\u00edtulo\n  - title (text, padr\u00e3o \"Um t\u00edtulo que diz tudo\"): T\u00edtulo\n  - subtitle (texto Markdown, padr\u00e3o \"Uma frase curta que explica o que \u00e9, para quem \u00e9 e por que importa.\"): Texto\n  - buttons (lista de objetos): Bot\u00f5es\n      - label (text, padr\u00e3o \"Saiba mais\"): Texto\n      - url (url, padr\u00e3o \"#\"): Link\n      - variant (\"primary\"|\"secondary\"|\"ghost\", padr\u00e3o \"primary\"): Estilo\n  - image (URL de imagem): Imagem\n  - layout (\"center\"|\"left\"|\"split\", padr\u00e3o \"center\"): Disposi\u00e7\u00e3o\n  - height (\"auto\"|\"tall\"|\"screen\", padr\u00e3o \"tall\"): Altura\n  - stack (boolean, padr\u00e3o false): Bot\u00f5es empilhados (estilo lista de links)\n\ntext \u2014 Texto: Texto livre em Markdown (t\u00edtulos, listas, tabelas, cita\u00e7\u00f5es, c\u00f3digo, [[links]]).\n  - title (text): T\u00edtulo\n  - markdown (texto Markdown, padr\u00e3o \"Escreva aqui em **Markdown**.\"): Conte\u00fado\n  - columns (1|2, padr\u00e3o 1): Colunas de texto\n\nnote \u2014 Nota: Mostra o conte\u00fado de uma nota do vault; atualiza sozinho quando a nota muda.\n  - path (caminho de nota, obrigat\u00f3rio): Nota\n  - showTitle (boolean, padr\u00e3o true): Mostrar t\u00edtulo\n  - showMeta (boolean, padr\u00e3o false): Mostrar data e tags\n\nnotes \u2014 Cole\u00e7\u00e3o de notas: Cart\u00f5es ou lista de v\u00e1rias notas (de uma pasta, uma tag ou escolhidas), com resumo; pode incluir o texto completo de cada uma logo abaixo.\n  - title (text): T\u00edtulo\n  - subtitle (textarea): Subt\u00edtulo\n  - source (\"folder\"|\"tag\"|\"list\"|\"recent\", padr\u00e3o \"folder\"): Origem\n  - folder (folder): Pasta\n  - tag (tag): Tag\n  - paths (textarea): Notas (uma por linha)\n  - layout (\"cards\"|\"list\"|\"grid\", padr\u00e3o \"cards\"): Apar\u00eancia\n  - columns (1|2|3|4, padr\u00e3o 3): Colunas\n  - limit (number, padr\u00e3o 24): M\u00e1ximo\n  - sort (\"title\"|\"modified\"|\"path\", padr\u00e3o \"title\"): Ordem\n  - excerpt (boolean, padr\u00e3o true): Mostrar resumo\n  - expand (boolean, padr\u00e3o false): Incluir o texto completo abaixo\n\nfeatures \u2014 Destaques: Grade de benef\u00edcios/recursos com \u00edcone (emoji), t\u00edtulo e texto.\n  - title (text): T\u00edtulo\n  - subtitle (textarea): Subt\u00edtulo\n  - columns (1|2|3|4, padr\u00e3o 3): Colunas\n  - items (lista de objetos): Itens\n      - icon (text, padr\u00e3o \"\u2728\"): \u00cdcone (emoji)\n      - title (text, padr\u00e3o \"Recurso\"): T\u00edtulo\n      - text (textarea, padr\u00e3o \"Uma frase sobre este recurso.\"): Texto\n\ncards \u2014 Cart\u00f5es: Cart\u00f5es com imagem, t\u00edtulo, texto, etiqueta e link (projetos, posts, produtos).\n  - title (text): T\u00edtulo\n  - subtitle (textarea): Subt\u00edtulo\n  - columns (1|2|3|4, padr\u00e3o 3): Colunas\n  - items (lista de objetos): Cart\u00f5es\n      - image (URL de imagem): Imagem\n      - tag (text): Etiqueta\n      - title (text, padr\u00e3o \"T\u00edtulo do cart\u00e3o\"): T\u00edtulo\n      - text (textarea): Texto\n      - url (url): Link\n\ngallery \u2014 Galeria: Grade de imagens com legenda; toque abre a imagem ampliada.\n  - title (text): T\u00edtulo\n  - columns (1|2|3|4, padr\u00e3o 3): Colunas\n  - items (lista de objetos): Imagens\n      - image (URL de imagem): Imagem\n      - caption (text): Legenda\n\nimage \u2014 Imagem: Uma imagem com legenda.\n  - src (URL de imagem, obrigat\u00f3rio): Imagem\n  - alt (text): Descri\u00e7\u00e3o (acessibilidade)\n  - caption (text): Legenda\n  - size (\"normal\"|\"wide\"|\"full\", padr\u00e3o \"wide\"): Tamanho\n  - rounded (boolean, padr\u00e3o true): Cantos arredondados\n\nvideo \u2014 V\u00eddeo: V\u00eddeo do YouTube, Vimeo ou arquivo .mp4/.webm.\n  - url (url, obrigat\u00f3rio): Link do v\u00eddeo\n  - caption (text): Legenda\n\nquote \u2014 Cita\u00e7\u00e3o: Cita\u00e7\u00e3o em destaque com autor.\n  - text (textarea, padr\u00e3o \"Simplicidade \u00e9 o \u00faltimo grau de sofistica\u00e7\u00e3o.\"): Cita\u00e7\u00e3o\n  - author (text, padr\u00e3o \"Leonardo da Vinci\"): Autor\n  - role (text): Cargo / origem\n  - image (URL de imagem): Foto\n\ntestimonials \u2014 Depoimentos: V\u00e1rios depoimentos em cart\u00f5es.\n  - title (text): T\u00edtulo\n  - columns (1|2|3|4, padr\u00e3o 3): Colunas\n  - items (lista de objetos): Depoimentos\n      - text (textarea, padr\u00e3o \"Mudou meu jeito de trabalhar.\"): Texto\n      - author (text, padr\u00e3o \"Ana\"): Nome\n      - role (text): Cargo\n      - image (URL de imagem): Foto\n\nstats \u2014 N\u00fameros: N\u00fameros grandes com r\u00f3tulo (m\u00e9tricas, conquistas).\n  - title (text): T\u00edtulo\n  - items (lista de objetos): N\u00fameros\n      - value (text, padr\u00e3o \"100+\"): Valor\n      - label (text, padr\u00e3o \"clientes\"): R\u00f3tulo\n\ntimeline \u2014 Linha do tempo: Eventos em ordem, com data, t\u00edtulo e texto (hist\u00f3ria, roteiro, carreira).\n  - title (text): T\u00edtulo\n  - subtitle (textarea): Subt\u00edtulo\n  - items (lista de objetos): Eventos\n      - date (text, padr\u00e3o \"2025\"): Data\n      - title (text, padr\u00e3o \"Marco\"): T\u00edtulo\n      - text (texto Markdown): Texto\n\nfaq \u2014 Perguntas: Perguntas frequentes que abrem e fecham.\n  - title (text): T\u00edtulo\n  - subtitle (textarea): Subt\u00edtulo\n  - items (lista de objetos): Perguntas\n      - q (text, padr\u00e3o \"Como funciona?\"): Pergunta\n      - a (texto Markdown, padr\u00e3o \"Explique aqui.\"): Resposta\n  - openFirst (boolean, padr\u00e3o true): Primeira aberta\n\ncta \u2014 Chamada: Faixa de chamada para a\u00e7\u00e3o com bot\u00f5es.\n  - title (text, padr\u00e3o \"Pronto para come\u00e7ar?\"): T\u00edtulo\n  - text (textarea, padr\u00e3o \"Leva menos de um minuto.\"): Texto\n  - buttons (lista de objetos): Bot\u00f5es\n      - label (text, padr\u00e3o \"Saiba mais\"): Texto\n      - url (url, padr\u00e3o \"#\"): Link\n      - variant (\"primary\"|\"secondary\"|\"ghost\", padr\u00e3o \"primary\"): Estilo\n\ncolumns \u2014 Colunas: Duas a quatro colunas de texto em Markdown.\n  - title (text): T\u00edtulo\n  - columns (1|2|3|4, padr\u00e3o 2): Colunas\n  - items (lista de objetos): Colunas\n      - title (text): T\u00edtulo\n      - markdown (texto Markdown, padr\u00e3o \"Texto da coluna.\"): Texto\n\npricing \u2014 Planos: Tabela de planos/pre\u00e7os com lista de itens e bot\u00e3o.\n  - title (text): T\u00edtulo\n  - subtitle (textarea): Subt\u00edtulo\n  - items (lista de objetos): Planos\n      - name (text, padr\u00e3o \"Plano\"): Nome\n      - price (text, padr\u00e3o \"R$ 0\"): Pre\u00e7o\n      - period (text, padr\u00e3o \"/m\u00eas\"): Per\u00edodo\n      - description (text): Descri\u00e7\u00e3o\n      - features (textarea, padr\u00e3o \"Item um\\nItem dois\"): Itens (um por linha)\n      - buttonLabel (text, padr\u00e3o \"Escolher\"): Bot\u00e3o\n      - url (url, padr\u00e3o \"#\"): Link\n      - highlight (boolean, padr\u00e3o false): Destacar\n\ncontact \u2014 Contato: Contato com e-mail, telefone e links (redes, portf\u00f3lio).\n  - title (text, padr\u00e3o \"Vamos conversar\"): T\u00edtulo\n  - text (textarea, padr\u00e3o \"Respondo em at\u00e9 um dia.\"): Texto\n  - email (text): E-mail\n  - phone (text): Telefone\n  - links (lista de objetos): Links\n      - label (text, padr\u00e3o \"GitHub\"): Nome\n      - url (url): Link\n\ncountdown \u2014 Contagem regressiva: Contagem at\u00e9 uma data (eventos, lan\u00e7amentos).\n  - title (text, padr\u00e3o \"Falta pouco\"): T\u00edtulo\n  - date (text, padr\u00e3o \"2030-01-01 09:00\"): Data e hora (AAAA-MM-DD HH:MM)\n  - done (text, padr\u00e3o \"Come\u00e7ou!\"): Texto quando chegar\n\ncode \u2014 C\u00f3digo: Bloco de c\u00f3digo com bot\u00e3o de copiar.\n  - title (text): T\u00edtulo\n  - language (text, padr\u00e3o \"js\"): Linguagem\n  - code (code, padr\u00e3o \"console.log(\\\"ol\u00e1\\\")\"): C\u00f3digo\n\ntoc \u2014 Sum\u00e1rio: Lista autom\u00e1tica das se\u00e7\u00f5es com t\u00edtulo desta p\u00e1gina.\n  - title (text, padr\u00e3o \"Nesta p\u00e1gina\"): T\u00edtulo\n\ndivider \u2014 Divisor: Separador visual ou espa\u00e7o.\n  - style (\"line\"|\"dots\"|\"wave\"|\"space\", padr\u00e3o \"line\"): Estilo\n\nhtml \u2014 HTML livre: HTML/CSS/JS pr\u00f3prio, inserido como est\u00e1 (use com cuidado).\n  - code (code, padr\u00e3o \"<div style=\\\"text-align:center\\\">Ol\u00e1!</div>\"): HTML\n\nbookcover \u2014 Capa do livro: Capa com t\u00edtulo, subt\u00edtulo, autor e editora (cl\u00e1ssica, moderna ou com imagem).\n  - title (text, padr\u00e3o \"O t\u00edtulo do livro\"): T\u00edtulo\n  - subtitle (text): Subt\u00edtulo\n  - author (text, padr\u00e3o \"Nome do autor\"): Autor\n  - publisher (text): Editora ou selo\n  - image (URL de imagem): Imagem\n  - style (\"classic\"|\"modern\"|\"image\", padr\u00e3o \"classic\"): Estilo\n\ntitlepage \u2014 Folha de rosto: P\u00e1gina com t\u00edtulo, subt\u00edtulo, autor e editora, cidade e ano.\n  - title (text, padr\u00e3o \"O t\u00edtulo do livro\"): T\u00edtulo\n  - subtitle (text): Subt\u00edtulo\n  - author (text, padr\u00e3o \"Nome do autor\"): Autor\n  - publisher (text): Editora ou selo\n  - place (text): Cidade\n  - year (text, padr\u00e3o \"7000\"): Ano\n\ncopyright \u2014 Cr\u00e9ditos e direitos: P\u00e1gina de cr\u00e9ditos: direitos autorais, edi\u00e7\u00e3o, ISBN, ficha catalogr\u00e1fica e equipe.\n  - markdown (texto Markdown, padr\u00e3o \"Copyright \u00a9 7000 Nome do autor\\n\\nTodos os direitos reservados. Nenhuma parte desta obra pode ser reproduzida sem autoriza\u00e7\u00e3o por escrito do autor.\\n\\n1\u00aa edi\u00e7\u00e3o\\n\\n**Revis\u00e3o:** Nome  \\n**Capa:** Nome  \\n**Diagrama\u00e7\u00e3o:** Urbe\\n\\nISBN 000-00-00000-00-0\"): Texto\n\ndedication \u2014 Dedicat\u00f3ria ou ep\u00edgrafe: P\u00e1gina curta e centralizada: dedicat\u00f3ria, agradecimento breve ou ep\u00edgrafe com autor.\n  - kind (\"dedication\"|\"epigraph\", padr\u00e3o \"dedication\"): Tipo\n  - markdown (texto Markdown, padr\u00e3o \"Para quem sempre acreditou.\"): Texto\n  - author (text): Autor da ep\u00edgrafe\n\nbooktoc \u2014 Sum\u00e1rio do livro: Sum\u00e1rio autom\u00e1tico com as partes e os cap\u00edtulos do livro, com links.\n  - title (text, padr\u00e3o \"Sum\u00e1rio\"): T\u00edtulo\n\npart \u2014 Parte: P\u00e1gina de abertura de uma parte do livro (Parte I, Parte II\u2026), com texto opcional.\n  - title (text, padr\u00e3o \"T\u00edtulo da parte\"): T\u00edtulo\n  - markdown (texto Markdown): Texto de abertura\n\nchapter \u2014 Cap\u00edtulo: Cap\u00edtulo numerado, come\u00e7ando em p\u00e1gina nova: t\u00edtulo, ep\u00edgrafe e texto escrito aqui ou puxado de uma nota.\n  - title (text, padr\u00e3o \"T\u00edtulo do cap\u00edtulo\"): T\u00edtulo\n  - source (\"text\"|\"note\", padr\u00e3o \"text\"): Texto de onde\n  - markdown (texto Markdown, padr\u00e3o \"Era uma vez uma cidade feita de notas.\\n\\nCada par\u00e1grafo ganha recuo na primeira linha, como num livro impresso.\\n\\n***\\n\\nUma linha com tr\u00eas asteriscos vira um ornamento de troca de cena.\"): Texto\n  - path (caminho de nota): Nota\n  - epigraph (textarea): Ep\u00edgrafe\n  - epigraphAuthor (text): Autor da ep\u00edgrafe\n  - numbered (boolean, padr\u00e3o true): Numerar o cap\u00edtulo\n  - dropCap (boolean, padr\u00e3o true): Letra capitular\n\nchapters \u2014 Cap\u00edtulos de uma pasta: Cada nota de uma pasta vira um cap\u00edtulo, na ordem escolhida (por nome, caminho ou data).\n  - folder (folder): Pasta\n  - sort (\"path\"|\"title\"|\"modified\", padr\u00e3o \"path\"): Ordem\n  - dropCap (boolean, padr\u00e3o true): Letra capitular\n\nabout \u2014 Sobre o autor: P\u00e1gina com foto e uma breve biografia do autor.\n  - title (text, padr\u00e3o \"Sobre o autor\"): T\u00edtulo\n  - image (URL de imagem): Foto\n  - markdown (texto Markdown, padr\u00e3o \"Nome do autor nasceu em \u2026 e escreve sobre \u2026\"): Texto\n\ncolophon \u2014 Colof\u00e3o: Nota final de produ\u00e7\u00e3o: fontes, papel, gr\u00e1fica e data de impress\u00e3o.\n  - markdown (texto Markdown, padr\u00e3o \"Este livro foi composto em EB Garamond e Cormorant Garamond e produzido com o Urbe.\"): Texto\n\nfree \u2014 Layout livre: Monte pe\u00e7a por pe\u00e7a: containers (empilhados, lado a lado ou em grade) com t\u00edtulos, par\u00e1grafos, imagens, bot\u00f5es e mais. Cada pe\u00e7a tem o pr\u00f3prio estilo, com valores diferentes para computador, tablet e celular.\n  - root (tree): Elementos\n  - sheet (\"flow\"|\"page\"|\"full\", padr\u00e3o \"page\"): No livro\n\nLAYOUT LIVRE (bloco \"free\"): props.root \u00e9 uma \u00e1rvore. Cada pe\u00e7a: {\"type\":\"<tipo>\",\"content\":{...},\"style\":{...},\"tablet\":{...},\"mobile\":{...},\"children\":[...]} (s\u00f3 \"box\" tem children). tablet vale at\u00e9 900px e mobile at\u00e9 600px; o que n\u00e3o mudar herda de style.\nTipos e content: box(tag,link); heading(text,level); text(text); image(src,alt,caption,link); button(label,url,variant); list(items,ordered); quote(text,author); icon(emoji); divider(); spacer(); video(url); note(path,showTitle); html(code); table(md); code(code,lang); formula(tex); badge(text); embed(url,title); pagebreak().\nEstilos: display=stack|row|grid|none; gap=medida css; columns=n\u00famero; minCol=medida css; justify=start|center|end|between|around|evenly; align=stretch|start|center|end|baseline; self=auto|start|center|end|stretch; order=n\u00famero; width=medida css; maxWidth=medida css; minHeight=medida css; height=medida css; aspect=1/1|4/3|3/2|16/9|21/9|3/4|2/3|9/16; fit=cover|contain; padding=medida css; margin=medida css; bg=cor; bg2=cor; angle=n\u00famero; bgImage; color=cor; border=medida css; borderStyle=solid|dashed|dotted|double; borderColor=cor; radius=medida css; shadow=none|soft|strong|glow; opacity=n\u00famero; font=heading|body|inter|manrope|grotesk|dmsans|outfit|playfair|fraunces|lora|merriweather|garamond|cormorant|crimson|baskerville|mono|system|serif; size=medida css; weight=300|400|500|600|700|800|900; lineHeight=n\u00famero; spacing=medida css; textAlign=left|center|right|justify; transform=none|uppercase|lowercase|capitalize; italic=yes|no; className; css.\nExemplo: {\"type\":\"box\",\"style\":{\"display\":\"row\",\"gap\":\"24px\",\"minCol\":\"260px\"},\"mobile\":{\"display\":\"stack\"},\"children\":[{\"type\":\"heading\",\"content\":{\"text\":\"Oi\",\"level\":2}},{\"type\":\"text\",\"content\":{\"text\":\"Par\u00e1grafo **em Markdown**.\"}}]}\nDicas: textos longos em Markdown aceitam [[links]] para notas. Blocos \"note\" e \"notes\" puxam o conte\u00fado real das notas e se atualizam sozinhos. Para aparecer no menu da barra, d\u00ea \"anchor\" e \"menu\":true no style da se\u00e7\u00e3o.";
